import'package:dierb_api_client/dierb_api_client.dart';import'package:dierb_core/dierb_core.dart';import'package:flutter/material.dart';class HistoryScreen extends StatefulWidget{const HistoryScreen({super.key});@override State<HistoryScreen>createState()=>_State();}class _State extends State<HistoryScreen>{final api=DierbApi();List<dynamic>orders=const[];bool loading=true;@override void initState(){super.initState();load();}@override void dispose(){api.close();super.dispose();}Future<void>load()async{final v=await api.orders();if(mounted)setState((){orders=v.where((x)=>['delivered','cancelled','rejected'].contains((x as Map)['status'])).toList();loading=false;});}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('سجل المبيعات')),body:loading?const Center(child:CircularProgressIndicator()):orders.isEmpty?const Center(child:Text('لا توجد طلبات منتهية')):RefreshIndicator(onRefresh:load,child:ListView.separated(padding:const EdgeInsets.all(14),itemCount:orders.length,separatorBuilder:(_,__)=>const SizedBox(height:8),itemBuilder:(_,i){final m=orders[i]as Map,s=OrderStatusCodec.fromStorage(m['status']),total=((m['totalPiasters']as num?)?.toDouble()??0)/100;return Card(child:ListTile(leading:Icon(s==OrderStatus.delivered?Icons.check_circle:Icons.cancel,color:s==OrderStatus.delivered?Colors.green:Colors.orange),title:Text((m['customerName']??'طلب ديرب').toString()),subtitle:Text(s.labelAr),trailing:Text('${total.toStringAsFixed(2)} ج.م')));})));}
